    params.push_back(std::make_unique<juce::AudioParameterInt>(juce::ParameterID{ "fx_wetDryMix", 1 }, "DSP Wet/Dry Balance (%)", 0, 100, 100));
    params.push_back(std::make_unique<juce::AudioParameterInt>(juce::ParameterID{ "fx_outLevel", 1 }, "DSP Output Level", 0, 100, 71));
    params.push_back(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{ "fx_stereoMix", 1 }, "DSP Stereo Aux Mix", true));
